sys_script.script:
(function executeRule(current, previous) {
    g_scratchpad.doppelTestedSig = JSON.stringify([
        current.getValue('api_version') || 'v1',
        current.getValue('organisation_code') || '',
        current.getValue('client_id') || '',
        '', '', '' // password fields are always empty in the browser after loading
    ]);
})(current, previous);
